with valid as (select id, customer_id, browser, started_at, country, concat_ws(',', device, country) as device_country_key from sessions where customer_id is not null), ranked as (select * from (select *, row_number() over (partition by customer_id order by started_at desc nulls first, id) as dedup_rank from valid) t where dedup_rank = 1), enriched as (select *, row_number() over (partition by browser order by started_at, id) as seq_no, row_number() over (partition by country order by started_at, id) as seq_no_2, first_value(country) ignore nulls over (partition by browser order by started_at, id rows between unbounded preceding and current row) as first_known_country from ranked) select id, browser, country, device_country_key, dedup_rank, seq_no, seq_no_2, first_known_country, case when country rlike '^(SG|TH)$' then 'PRIORITY' when country rlike '^(US|JP)$' then 'CORE' else 'GROUP_A' end as country_zone from enriched order by dedup_rank desc
